<?php
session_start(); require_once 'database.php';
if (isset($_SESSION['loggedinEmail'])) { header('Location: dashboard.php'); exit; }
$errors=[]; $fullName=''; $email='';
// Everyone who signs up is a job seeker. Admin (employer) accounts are promoted
// directly in the database, so strangers can't give themselves admin rights.
$role='user';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $fullName=trim($_POST['full_name']??''); $email=trim($_POST['email']??''); $password=$_POST['password']??''; $confirmPassword=$_POST['confirm_password']??'';
 if($fullName==='')$errors['full_name']='Full name is required.'; if($email==='')$errors['email']='Email address is required.'; elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email address.'; if($password==='')$errors['password']='Password is required.'; elseif(strlen($password)<8)$errors['password']='Use at least 8 characters.'; elseif(!preg_match('/[^a-zA-Z0-9]/',$password))$errors['password']='Include at least one special character.'; if($confirmPassword==='')$errors['confirm_password']='Please confirm your password.'; elseif($password!==$confirmPassword)$errors['confirm_password']='Passwords do not match.';
 if(!$errors){$check=$conn->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$check->bind_param('s',$email);$check->execute();if($check->get_result()->fetch_assoc())$errors['email']='This email has already been registered. Please log in.';else{$hash=password_hash($password,PASSWORD_DEFAULT);$add=$conn->prepare('INSERT INTO users (full_name,email,password,role) VALUES (?,?,?,?)');$add->bind_param('ssss',$fullName,$email,$hash,$role);if($add->execute()){session_regenerate_id(true);$_SESSION['loggedinEmail']=$email;$_SESSION['userName']=$fullName;$_SESSION['userId']=$conn->insert_id;$_SESSION['userRole']=$role;header('Location: dashboard.php');exit;}$errors['email']='We could not create your account. Please try again.';}}
}
?>
