echo isset($errors['password'])?'is-invalid':''; ?>" id="password" type="password" name="password"><?php if(isset($errors['password'])):?><div class="invalid-feedback"><?php echo $errors['password']; ?></div><?php else:?><div class="form-text">At least 8 characters and one special character.</div><?php endif;?></div><div class="mb-4"><label class="fw-semibold mb-1" for="confirm_password">Confirm password</label><input class="form-control <?php echo isset($errors['confirm_password'])?'is-invalid':''; ?>" id="confirm_password" type="password" name="confirm_password"><?php if(isset($errors['confirm_password'])):?><div class="invalid-feedback"><?php echo $errors['confirm_password']; ?></div><?php endif;?></div><button class="btn btn-vuka w-100" type="submit">Create account</button></form><p class="text-center text-secondary mt-4 mb-0">Already have an account? <a class="fw-bold text-dark" href="login.php">Log in</a></p></section></main></body></html>
